<?php require_once __DIR__.'/includes/auth.php'; require_login(['admin']);$pdo=db();$results=$pdo->query("SELECT r.id,r.tracking_no,c.course_code,c.course_title,r.current_stage_id,s.stage_name FROM result_records r JOIN courses c ON c.id=r.course_id JOIN status_stages s ON s.id=r.current_stage_id ORDER BY r.updated_at DESC")->fetchAll();$stages=$pdo->query("SELECT s.id,s.stage_name,s.office_id,o.office_name FROM status_stages s LEFT JOIN offices o ON o.id=s.office_id WHERE s.stage_order BETWEEN 2 AND 8 ORDER BY CASE WHEN s.stage_order=8 THEN 99 ELSE s.stage_order END")->fetchAll();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rid=(int)($_POST['result_id']??0);$to=(int)($_POST['to_stage_id']??0);$received=trim($_POST['received_by']??'');$remarks=trim($_POST['remarks']??'');$s=$pdo->prepare('SELECT * FROM result_records WHERE id=?');$s->execute([$rid]);$r=$s->fetch();$ss=$pdo->prepare('SELECT * FROM status_stages WHERE id=?');$ss->execute([$to]);$stage=$ss->fetch();if(!$r||!$stage||$r['current_stage_id']==$to){$error='Please select a valid result and a different new status.';}else{try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO result_movements(result_id,from_stage_id,to_stage_id,from_office_id,to_office_id,handed_over_by,received_by,remarks,user_id) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$rid,$r['current_stage_id'],$to,$r['current_office_id'],$stage['office_id'],current_user()['name'],$received,$remarks,current_user()['id']]);$pdo->prepare('UPDATE result_records SET current_stage_id=?,current_office_id=?,current_since=? WHERE id=?')->execute([$to,$stage['office_id'],date('Y-m-d H:i:s'),$rid]);$pdo->commit();$event=$stage['stage_name'];log_activity($rid,$event,$remarks,$received);send_notification($rid,$event);flash('success','Handover saved and tracking status updated.');redirect('handover.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not save handover. '.$e->getMessage();}}}
$pageTitle='Handover | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Secretary / Admin Portal</span></div></div><a class="portal-back" href="admin-dashboard.php">← Dashboard</a></header><main class="form-main"><div class="page-title"><div><span class="kicker">MOVEMENT LOG</span><h1>Record Handover</h1><p>Every movement is logged with an automatic date and time.</p></div></div><?php if($msg=get_flash('success')):?><div class="success-box"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="danger-box"><?=e($error)?></div><?php endif;?><form class="panel form-panel" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Course / Result<select name="result_id" required><option value="">Select result</option><?php foreach($results as $r):?><option value="<?=$r['id']?>"><?=e($r['tracking_no'].' — '.$r['course_code'].' '.$r['course_title'].' | Current: '.$r['stage_name'])?></option><?php endforeach;?></select></label><label>New Status<select name="to_stage_id" required><option value="">Select new status</option><?php foreach($stages as $s):?><option value="<?=$s['id']?>"><?=e($s['stage_name'].' — '.$s['office_name'])?></option><?php endforeach;?></select></label><label>Handed Over By<input value="<?=e(current_user()['name'])?>" readonly></label><label>Received By<input name="received_by" placeholder="Receiving officer"></label><label class="full">Remarks<textarea name="remarks" rows="5" placeholder="Optional internal movement note. Public users will not see this."></textarea></label></div><div class="notice">Date and time are generated automatically. Movement records are appended to the audit history and are not edited in place.</div><div class="form-actions"><a class="secondary-btn" href="admin-dashboard.php">Cancel</a><button class="primary-btn" type="submit">Save Handover</button></div></form></main><?php require __DIR__.'/includes/footer.php'; ?>
